WITH parsed AS (SELECT id, service, log_ts, payload_json, context['trace'] AS trace, COALESCE(context['version'], 'unknown') AS version_or_default FROM app_logs) SELECT *, LAST_VALUE(trace) IGNORE NULLS OVER w_grp last_known_trace, ROW_NUMBER() OVER (PARTITION BY service ORDER BY log_ts DESC, id) event_seq, LAST_VALUE(trace) IGNORE NULLS OVER (PARTITION BY service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_trace_2 FROM parsed WINDOW w_grp AS (ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
